export const Image: Story = {
  parameters: {
    docs: {
      description: { story: "Set `variant="image"` on `AttachmentMedia` and render an `<img>` inside it. Use `orientation="vertical"` to stack the media above the content. Vertical image media sits flush with the card's top edge like `CardMedia`, as a 4:3 photo above the content or a square that fills the card on its own.

Image attachments open in a [Lightbox](/docs/components/lightbox). Wrap the media in `LightboxTrigger`, render it as an `AttachmentTrigger`, and attach the trigger's `imageRef` to the thumbnail. The trigger takes the media's place, so the open transition grows the thumbnail into the slide and reuses its pixels until the full image loads, while the whole card stays clickable. Match each trigger's `index` to its `LightboxItem`, starting at zero.

```tsx
<Lightbox>
  <AttachmentGroup>
    {images.map((image, index) => (
      <Attachment key={image.name} orientation="vertical">
        <LightboxTrigger
          aria-label={`Open ${image.name}`}
          index={index}
          render={<AttachmentTrigger />}
        >
          {({ imageRef }) => (
            <AttachmentMedia variant="image">
              <img ref={imageRef} src={image.thumbnail} alt={image.alt} />
            </AttachmentMedia>
          )}
        </LightboxTrigger>
        <AttachmentContent>{/* title and description */}</AttachmentContent>
        <AttachmentRemove aria-label={`Remove ${image.name}`} />
      </Attachment>
    ))}
  </AttachmentGroup>
  <LightboxContent aria-label="Attached images">{/* one LightboxItem per image */}</LightboxContent>
</Lightbox>
```" },
      source: { code: "import {
  Lightbox,
  LightboxCaption,
  LightboxClose,
  LightboxContent,
  LightboxFooter,
  LightboxHeader,
  LightboxItem,
  LightboxMedia,
  LightboxNext,
  LightboxPrevious,
  LightboxSlide,
  LightboxSlides,
  LightboxStepIndicator,
  LightboxTrigger,
  LightboxZoom,
  LightboxZoomIn,
  LightboxZoomOut,
} from "@/registry/erbium/blocks/lightbox";
import {
  Attachment,
  AttachmentContent,
  AttachmentDescription,
  AttachmentGroup,
  AttachmentMedia,
  AttachmentRemove,
  AttachmentTitle,
  AttachmentTrigger,
} from "@/registry/erbium/ui/attachment";

const images = [
  {
    alt: "A workspace with long desks and hanging lights",
    meta: "PNG · 820 KB",
    name: "workspace.png",
    src: "https://images.unsplash.com/photo-1497366754035-f200968a6e72",
  },
  {
    alt: "A plant-filled desk by large windows",
    meta: "JPG · 1.1 MB",
    name: "desk-reference.jpg",
    src: "https://images.unsplash.com/photo-1497215728101-856f4ea42174",
  },
  {
    alt: "An office with a central table and chairs",
    meta: "JPG · 940 KB",
    name: "office-reference.jpg",
    src: "https://images.unsplash.com/photo-1497366811353-6870744d04b2",
  },
];

export default function AttachmentImageExample() {
  return (
    <Lightbox>
      <div className="mx-auto w-full max-w-sm py-12">
        <AttachmentGroup className="w-full">
          {images.map((image, index) => (
            <Attachment key={image.name} orientation="vertical">
              <LightboxTrigger
                aria-label={`Open ${image.name}`}
                className="cursor-zoom-in"
                index={index}
                render={<AttachmentTrigger />}
              >
                {({ imageRef }) => (
                  <AttachmentMedia variant="image">
                    <img
                      alt={image.alt}
                      height={360}
                      ref={imageRef}
                      src={`${image.src}?auto=format&fit=crop&w=480&h=360&q=80`}
                      width={480}
                    />
                  </AttachmentMedia>
                )}
              </LightboxTrigger>
              <AttachmentContent>
                <AttachmentTitle>{image.name}</AttachmentTitle>
                <AttachmentDescription>{image.meta}</AttachmentDescription>
              </AttachmentContent>
              <AttachmentRemove aria-label={`Remove ${image.name}`} />
            </Attachment>
          ))}
        </AttachmentGroup>
      </div>

      <LightboxContent aria-label="Attached images">
        <LightboxSlides aria-label="Attached images" aria-roledescription="carousel">
          {images.map((image, index) => (
            <LightboxSlide key={image.name}>
              <LightboxItem
                aria-label={`${index + 1} of ${images.length}`}
                aria-roledescription="slide"
                caption={image.name}
                index={index}
              >
                <LightboxZoom>
                  <LightboxMedia height={1350} width={1800}>
                    <img
                      alt={image.alt}
                      height={1350}
                      src={`${image.src}?auto=format&fit=crop&w=1800&h=1350&q=85`}
                      width={1800}
                    />
                  </LightboxMedia>
                </LightboxZoom>
              </LightboxItem>
            </LightboxSlide>
          ))}
        </LightboxSlides>

        <LightboxHeader className="grid grid-cols-[1fr_auto_1fr]">
          <div />
          <LightboxStepIndicator labels={images.map((image) => image.name)} />
          <div className="flex items-center gap-2 justify-self-end">
            <LightboxZoomOut />
            <LightboxZoomIn />
            <LightboxClose />
          </div>
        </LightboxHeader>

        <LightboxPrevious />
        <LightboxNext />

        <LightboxFooter>
          <LightboxCaption />
        </LightboxFooter>
      </LightboxContent>
    </Lightbox>
  );
}
" },
    },
  },
  render: ImageExample,
};

export const States: Story = {
  parameters: {
    docs: {
      description: { story: "Set `state` to reflect the upload lifecycle. `uploading` and `processing` shimmer the title, and `error` switches to a error treatment." },
      source: { code: "import { Icon } from "@/registry/erbium/ui/icon";

import {
  Attachment,
  AttachmentAction,
  AttachmentActions,
  AttachmentContent,
  AttachmentDescription,
  AttachmentMedia,
  AttachmentRemove,
  AttachmentTitle,
} from "@/registry/erbium/ui/attachment";
import { Spinner } from "@/registry/erbium/ui/spinner";

export default function AttachmentStatesExample() {
  return (
    <div className="mx-auto flex w-full max-w-sm flex-col gap-related py-12">
      <Attachment state="idle" className="w-full">
        <AttachmentMedia>
          <Icon name="clock-01" />
        </AttachmentMedia>
        <AttachmentContent>
          <AttachmentTitle>selected-file.pdf</AttachmentTitle>
          <AttachmentDescription>Ready to upload</AttachmentDescription>
        </AttachmentContent>
        <AttachmentRemove aria-label="Remove selected-file.pdf" />
      </Attachment>
      <Attachment state="uploading" className="w-full">
        <AttachmentMedia>
          <Spinner />
        </AttachmentMedia>
        <AttachmentContent>
          <AttachmentTitle>design-system.zip</AttachmentTitle>
          <AttachmentDescription>Uploading · 64%</AttachmentDescription>
        </AttachmentContent>
        <AttachmentRemove aria-label="Cancel upload" />
      </Attachment>
      <Attachment state="processing" className="w-full">
        <AttachmentMedia>
          <Icon name="file-text" />
        </AttachmentMedia>
        <AttachmentContent>
          <AttachmentTitle>market-research.pdf</AttachmentTitle>
          <AttachmentDescription>Processing document</AttachmentDescription>
        </AttachmentContent>
        <AttachmentRemove aria-label="Remove market-research.pdf" />
      </Attachment>
      <Attachment state="error" className="w-full">
        <AttachmentMedia>
          <Icon name="alert-square" />
        </AttachmentMedia>
        <AttachmentContent>
          <AttachmentTitle>financial-model.xlsx</AttachmentTitle>
          <AttachmentDescription>Upload failed. Try again.</AttachmentDescription>
        </AttachmentContent>
        <AttachmentActions>
          <AttachmentAction aria-label="Retry upload">
            <Icon name="refresh-cw" />
          </AttachmentAction>
        </AttachmentActions>
        <AttachmentRemove aria-label="Remove financial-model.xlsx" />
      </Attachment>
      <Attachment state="done" className="w-full">
        <AttachmentMedia>
          <Icon name="check" />
        </AttachmentMedia>
        <AttachmentContent>
          <AttachmentTitle>uploaded-report.pdf</AttachmentTitle>
          <AttachmentDescription>Uploaded · 1.8 MB</AttachmentDescription>
        </AttachmentContent>
        <AttachmentRemove aria-label="Remove uploaded-report.pdf" />
      </Attachment>
    </div>
  );
}
" },
    },
  },
  render: StatesExample,
};

